"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def MultiplyMatrices(A, B, r1, c1, r2, c2):
    if (c1 != r2):
        return 'Invalid matrix dimensions'
    C = [[0 for _ in range(c2)] for _ in range(r1)]
    for i in range(0, r1):
        for j in range(0, c2):
            for k in range(0, c1):
                C[i][j] = (C[i][j] + (A[i][k] * B[k][j]))
    return C
